INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5750, 'rolling forecast', '/ˈroʊlɪŋ ˈfɔːrkæst/', 'noun', '{"zh-TW":["滾動預測"],"en":["a continuously updated projection extending a set number of months ahead"]}', NULL, 'use a rolling forecast / rolling forecast model', '[{"en":"The finance team uses a rolling forecast instead of fixed annual budgets.","zh-TW":"財務團隊使用滾動預測而非固定年度預算。"},{"en":"A rolling forecast provides more accurate and current projections.","zh-TW":"滾動預測提供了更準確和最新的預測。"}]', NULL, NULL, 5, 5750, NULL),
(5751, 'rollout', '/ˈroʊlaʊt/', 'noun', '{"zh-TW":["推出；逐步部署"],"en":["the gradual introduction of a product or system to users"]}', NULL, 'phased rollout / nationwide rollout / rollout plan / product rollout', '[{"en":"The phased rollout allowed issues to be fixed before full launch.","zh-TW":"分階段推出允許在全面上市前修復問題。"},{"en":"The software rollout was completed across all offices in six weeks.","zh-TW":"軟體部署在六週內完成了所有辦公室的覆蓋。"}]', '{"verb":"roll out"}', NULL, 3, 5751, 927),
(5752, 'rollout plan', '/ˈroʊlaʊt plæn/', 'noun', '{"zh-TW":["推出計劃；部署計劃"],"en":["a detailed schedule for implementing a new product or system"]}', NULL, 'create a rollout plan / follow the rollout plan', '[{"en":"The rollout plan described the phased launch across 10 regions.","zh-TW":"推出計劃描述了在10個地區的分階段推出。"},{"en":"A clear rollout plan minimizes disruption to daily operations.","zh-TW":"清晰的部署計劃最大限度地減少了對日常運營的干擾。"}]', NULL, NULL, 4, 5752, NULL),
(5753, 'rollover', '/ˈrəʊləʊvər/', 'noun', '{"zh-TW":["展期；滾存；轉存"],"en":["the extension of a debt or deposit beyond its maturity; the transfer of funds to a new account"]}', NULL, 'loan rollover / bond rollover / IRA rollover', '[{"en":"The bank agreed to a rollover of the short-term loan for an additional six months.","zh-TW":"銀行同意將短期貸款展期六個月。"},{"en":"Pension savers can use a rollover to transfer funds to a new retirement account tax-free.","zh-TW":"退休儲蓄者可以使用滾存方式將資金免稅轉入新的退休帳戶。"}]', NULL, NULL, 3, 5753, NULL),
(5754, 'room', '/ruːm/', 'noun', '{"zh-TW":["房間；空間"],"en":["a section of a building","available space"]}', NULL, 'meeting room / room for improvement', '[{"en":"There is room for improvement.","zh-TW":"還有改善的空間。"},{"en":"Book the meeting room for 2 p.m.","zh-TW":"預訂下午2點的會議室。"}]', '{"noun":"room","adjective":"roomy"}', NULL, 1, 5754, NULL),
(5755, 'room amenity', '/''ruːm əˈmiːnɪti/', 'noun', '{"zh-TW":["客房設施；房間備品"],"en":["items provided in a hotel room for the comfort and convenience of guests"]}', NULL, 'complimentary room amenity / luxury room amenity / standard room amenity', '[{"en":"The room amenity included a coffee maker, bathrobe, and toiletry kit.","zh-TW":"客房設施包括咖啡機、浴袍和盥洗用品套裝。"},{"en":"Guests can request additional room amenities from the housekeeping department.","zh-TW":"客人可以向客房服務部門索取額外的客房設施。"}]', NULL, NULL, 4, 5755, NULL),
(5756, 'room service', '/ruːm ˈsɜːrvɪs/', 'noun', '{"zh-TW":["客房服務"],"en":["the delivery of food and drinks to hotel rooms"]}', NULL, 'order room service / room service menu', '[{"en":"We ordered room service after arriving late at night.","zh-TW":"我們深夜抵達後點了客房服務。"},{"en":"Room service is available 24 hours a day.","zh-TW":"客房服務全天24小時提供。"}]', NULL, NULL, 4, 5756, NULL),
(5757, 'room upgrade', '/''ruːm ˌʌpˈɡreɪd/', 'noun', '{"zh-TW":["房間升級"],"en":["the allocation of a better or larger hotel room than originally booked"]}', NULL, 'complimentary room upgrade / receive a room upgrade / request a room upgrade', '[{"en":"As a gold member, she received a complimentary room upgrade to a suite.","zh-TW":"作為黃金會員，她獲得了免費升級至套房的待遇。"},{"en":"Room upgrades may be available at check-in depending on availability.","zh-TW":"房間升級可能在辦理入住手續時根據空房情況提供。"}]', NULL, NULL, 4, 5757, NULL),
(5758, 'root cause analysis', '/ruːt kɔːz əˈnælɪsɪs/', 'noun', '{"zh-TW":["根本原因分析"],"en":["a method for identifying the underlying cause of a problem"]}', NULL, 'conduct a root cause analysis / root cause analysis report / root cause analysis tools', '[{"en":"Root cause analysis revealed a software bug caused the outage.","zh-TW":"根本原因分析顯示軟體錯誤導致了中斷。"},{"en":"The team used root cause analysis to prevent recurrence.","zh-TW":"團隊使用根本原因分析防止問題再次發生。"}]', '{"abbreviation":"RCA"}', NULL, 5, 5758, NULL),
(5759, 'rotate', '/roʊˈteɪt/', 'verb', '{"zh-TW":["輪換；旋轉"],"en":["to move in a circle; to take turns"]}', '{"root":{"text":"rot","meaning":"wheel (輪)"},"suffix":{"text":"-ate","meaning":"使..."}}', 'rotate duties / job rotation / rotating schedule', '[{"en":"Staff rotate between departments quarterly.","zh-TW":"員工每季度在部門間輪換。"},{"en":"The chairperson role rotates annually.","zh-TW":"主席一職每年輪換。"}]', '{"noun":"rotation","adjective":"rotating, rotational"}', NULL, 2, 5759, NULL),
(5760, 'rotation', '/roʊˈteɪʃən/', 'noun', '{"zh-TW":["輪調；輪換"],"en":["systematically moving employees between different roles or departments"]}', NULL, 'job rotation / rotation program / staff rotation', '[{"en":"Job rotation helps employees develop a broader skill set.","zh-TW":"職位輪調幫助員工培養更廣泛的技能。"},{"en":"The graduate program includes a rotation through all business units.","zh-TW":"研究生計劃包括在所有業務單位的輪調。"}]', '{"verb":"rotate","adjective":"rotating"}', NULL, 3, 5760, 928),
(5761, 'roughly', '/ˈrʌfli/', 'adverb', '{"zh-TW":["大約；粗略地"],"en":["approximately; in a rough way"]}', '{"root":{"text":"rough","meaning":"rough (粗糙)"},"suffix":{"text":"-ly","meaning":"副詞後綴"}}', 'roughly equal / roughly speaking / roughly estimated', '[{"en":"The project will cost roughly $100,000.","zh-TW":"項目大約花費十萬美元。"},{"en":"Roughly 60% of staff attended.","zh-TW":"大約60%的員工出席了。"}]', '{"adjective":"rough"}', NULL, 3, 5761, NULL),
(5762, 'round', '/raʊnd/', 'noun', '{"zh-TW":["一輪；回合"],"en":["a series or cycle","approximately"]}', NULL, 'round of funding / year-round', '[{"en":"The startup raised a second round of funding.","zh-TW":"新創公司完成了第二輪融資。"},{"en":"The resort is open year-round.","zh-TW":"度假村全年開放。"}]', '{"noun":"round","adjective":"round","verb":"round","adverb":"around"}', NULL, 2, 5762, NULL),
(5763, 'round-the-clock', '/ˌraʊnd ðə ˈklɒk/', 'adjective', '{"zh-TW":["全天候的；24小時的"],"en":["continuing or available at all times, day and night"]}', NULL, 'round-the-clock support / round-the-clock operations', '[{"en":"The call center provides round-the-clock customer support.","zh-TW":"呼叫中心提供全天候客戶支援。"},{"en":"Emergency services operate on a round-the-clock basis.","zh-TW":"緊急服務全天候運作。"}]', NULL, NULL, 5, 5763, NULL),
(5764, 'roundtrip', '/ˈraʊndtrɪp/', 'noun', '{"zh-TW":["來回旅程"],"en":["a journey to a place and back again"]}', NULL, 'roundtrip ticket / roundtrip fare', '[{"en":"A roundtrip ticket is usually cheaper than two one-way tickets.","zh-TW":"來回票通常比兩張單程票便宜。"},{"en":"We booked roundtrip flights to London.","zh-TW":"我們預訂了倫敦的來回機票。"}]', NULL, NULL, 3, 5764, NULL),
(5765, 'route optimization', '/''ruːt ˌɒptɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["路線優化"],"en":["the process of finding the most efficient route for delivering goods or providing services"]}', NULL, 'implement route optimization / route optimization software / benefit of route optimization', '[{"en":"Route optimization software reduced delivery times by twenty percent.","zh-TW":"路線優化軟體將配送時間縮短了百分之二十。"},{"en":"The logistics company uses AI-powered route optimization to plan driver schedules.","zh-TW":"這家物流公司使用人工智慧驅動的路線優化來規劃司機行程。"}]', NULL, NULL, 5, 5765, NULL),
(5766, 'route planning', '/''ruːt ˌplænɪŋ/', 'noun', '{"zh-TW":["路線規劃；行程規劃"],"en":["the process of determining the best path for delivery vehicles to minimize time and cost"]}', NULL, 'efficient route planning / route planning software / optimize route planning', '[{"en":"Advanced route planning software helps logistics companies reduce delivery costs.","zh-TW":"先進的路線規劃軟體幫助物流公司降低配送成本。"},{"en":"Manual route planning is being replaced by AI-driven systems.","zh-TW":"手動路線規劃正在被人工智慧驅動的系統所取代。"}]', NULL, NULL, 5, 5766, NULL),
(5767, 'router', '/ˈraʊtər/', 'noun', '{"zh-TW":["路由器"],"en":["a device that directs internet traffic"]}', NULL, 'wireless router / router settings', '[{"en":"Restart the router to fix the connection.","zh-TW":"重啟路由器來修復連線。"},{"en":"The wireless router covers the whole house.","zh-TW":"無線路由器覆蓋整棟房子。"}]', NULL, NULL, 2, 5767, NULL),
(5768, 'routine', '/ruːˈtiːn/', 'noun', '{"zh-TW":["例行公事；日常工作","例行的；常規的"],"en":["a regular way of doing things","regular; done as part of normal procedure"]}', NULL, 'daily routine / routine maintenance / routine procedure; routine check / routine inspection / routine maintenance', '[{"en":"Routine maintenance is scheduled for Sunday.","zh-TW":"例行維護安排在週日。"},{"en":"It became part of the daily routine.","zh-TW":"它成為了日常工作的一部分。"},{"en":"This is just a routine inspection.","zh-TW":"這只是例行檢查。"},{"en":"Routine maintenance keeps equipment running.","zh-TW":"例行維護使設備正常運行。"}]', '{"adjective":"routine","adverb":"routinely","noun":"routine"}', NULL, 3, 5768, 212),
(5769, 'royalty payment', '/ˈrɔɪəlti ˈpeɪmənt/', 'noun', '{"zh-TW":["版稅；專利使用費"],"en":["periodic payments made for the right to use intellectual property"]}', NULL, 'receive royalty payments / royalty payment structure', '[{"en":"The inventor receives annual royalty payments from the licensing deal.","zh-TW":"發明人從授權協議中獲得年度版稅。"},{"en":"Royalty payments are calculated as a percentage of licensed product sales.","zh-TW":"版稅根據授權產品銷售額的百分比計算。"}]', '{"verb":"license"}', NULL, 5, 5769, NULL),
(5770, 'RSU', '/ˌɑːr es ˈjuː/', 'noun', '{"zh-TW":["限制性股票單位"],"en":["restricted stock unit; shares awarded to employees that vest over time"]}', NULL, 'RSU vesting / RSU award / receive RSUs', '[{"en":"She received 500 RSUs as part of her compensation package.","zh-TW":"她收到了500個限制性股票單位作為薪酬方案的一部分。"},{"en":"RSUs provide ownership stake without requiring upfront purchase.","zh-TW":"限制性股票單位提供所有權份額，無需預先購買。"}]', '{"full form":"restricted stock unit"}', NULL, 1, 5770, NULL),
(5771, 'RSVP', '/ɑːr ɛs viː piː/', 'verb', '{"zh-TW":["回覆邀請"],"en":["to respond to an invitation"]}', NULL, 'please RSVP / RSVP by Friday', '[{"en":"Please RSVP by Friday to confirm your attendance.","zh-TW":"請在週五前回覆以確認您的出席。"},{"en":"We need to finalize the guest list, so RSVP is required.","zh-TW":"我們需要確定賓客名單，因此請回覆邀請。"}]', NULL, NULL, 1, 5771, NULL),
(5772, 'rubric', '/''ruːbrɪk/', 'noun', '{"zh-TW":["評分標準；評分規範"],"en":["a set of criteria used to evaluate or assess student work"]}', NULL, 'grading rubric / assessment rubric / rubric-based evaluation', '[{"en":"The teacher shared the rubric so students would understand how their essays would be graded.","zh-TW":"老師分享了評分標準，讓學生了解他們的文章將如何被評分。"},{"en":"A detailed rubric helps ensure consistent and fair grading across all submissions.","zh-TW":"詳細的評分標準有助於確保所有提交作業的評分一致且公平。"}]', NULL, NULL, 2, 5772, NULL),
(5773, 'rule', '/ruːl/', 'noun', '{"zh-TW":["規則；法規"],"en":["an official instruction"]}', NULL, 'follow the rules / rule out / as a rule / rule of thumb', '[{"en":"All participants must follow the rules.","zh-TW":"所有參與者必須遵守規則。"},{"en":"We cannot rule out the possibility.","zh-TW":"我們不能排除這種可能性。"}]', '{"verb":"rule","noun":"ruler, ruling"}', NULL, 1, 5773, NULL),
(5774, 'run', '/rʌn/', 'verb', '{"zh-TW":["【主要意義-動詞】跑；運行","【次要意義-動詞】管理；經營（業務）","【次要意義-名詞】一連串（事件）；連續期間","【次要意義-名詞】（機器）運作期間"],"en":["[primary] to move quickly on foot; to operate","[secondary - verb] to manage or operate a business or organization","[secondary - noun] a continuous series or period","[secondary - noun] the operation of a machine or system"]}', NULL, 'run a business / run a meeting / in the long run / a run on the bank / on the run', '[{"en":"She has run the family business for over 15 years.","zh-TW":"她已經經營家族企業超過15年了。"},{"en":"In the long run, investing in training pays off for companies.","zh-TW":"從長遠來看，投資培訓對公司來說是值得的。"},{"en":"The factory had a production run of 50,000 units last month.","zh-TW":"上個月工廠的生產批次達到了5萬件。"}]', '{"noun":"runner, running","adjective":"running"}', '動詞 run = 「管理/經營」是 TOEIC 極高頻用法，in the long run（從長遠來看）是必考片語，a production run（生產批次）出現在製造業文章中。', 1, 5774, NULL),
(5775, 'run rate', '/rʌn reɪt/', 'noun', '{"zh-TW":["年化運行率；估算全年業績"],"en":["an extrapolation of current financial performance to a full-year basis"]}', NULL, 'annual run rate / revenue run rate / calculate the run rate', '[{"en":"The company''s revenue run rate reached $100 million after Q2.","zh-TW":"公司第二季後的收入年化運行率達到1億美元。"},{"en":"Run rate is useful for startups that haven''t completed a full year.","zh-TW":"年化運行率對尚未完成一整年的新創公司很有用。"}]', NULL, NULL, 3, 5775, NULL),
(5776, 'running costs', '/ˈrʌnɪŋ kɒsts/', 'noun', '{"zh-TW":["運營成本；日常費用"],"en":["the ongoing expenses of operating a business or asset"]}', NULL, 'reduce running costs / calculate running costs', '[{"en":"Solar panels reduce the running costs of the factory significantly.","zh-TW":"太陽能板顯著降低了工廠的運營成本。"},{"en":"Running costs must be factored into any financial projection.","zh-TW":"任何財務預測都必須考慮運營成本。"}]', NULL, NULL, 5, 5776, NULL),
(5777, 'runtime', '/ˈrʌntaɪm/', 'noun', '{"zh-TW":["運行時；執行期間"],"en":["the period during which a program is running; an environment supporting program execution"]}', NULL, 'runtime error / runtime environment / at runtime', '[{"en":"The runtime error occurred because of an invalid memory access.","zh-TW":"由於無效的記憶體訪問，發生了運行時錯誤。"},{"en":"The application dynamically loads configurations at runtime.","zh-TW":"應用程式在運行時動態加載配置。"}]', NULL, NULL, 3, 5777, NULL),
(5778, 'runway', '/ˈrʌnweɪ/', 'noun', '{"zh-TW":["資金跑道；可支撐時間"],"en":["the amount of time a startup can operate before running out of cash"]}', NULL, 'extend the runway / 12 months of runway / calculate runway', '[{"en":"With $3M in the bank and a $250K burn rate, they had 12 months of runway.","zh-TW":"銀行有300萬美元，燒錢速度25萬美元，他們有12個月的資金跑道。"},{"en":"Raising a new round extended the company''s runway by two years.","zh-TW":"新一輪融資將公司的資金跑道延長了兩年。"}]', NULL, NULL, 2, 5778, NULL),
(5779, 'résumé', '/ˈrezjʊmeɪ/', 'noun', '{"zh-TW":["履歷；簡歷"],"en":["a document summarizing an individual''s work experience and qualifications"]}', NULL, 'submit a résumé / update your résumé / résumé review', '[{"en":"She tailored her résumé to highlight relevant experience.","zh-TW":"她客製化了簡歷以突出相關經驗。"},{"en":"A strong résumé increases the chance of landing an interview.","zh-TW":"一份強力的履歷提高了獲得面試機會的可能性。"}]', '{"alternative":"CV (curriculum vitae)","plural":"résumés"}', NULL, 2, 5779, NULL),
(5780, 'SaaS', '/sæs/', 'noun', '{"zh-TW":["軟體即服務"],"en":["software as a service; cloud-based software accessed via subscription"]}', NULL, 'SaaS platform / SaaS model / SaaS product / switch to SaaS', '[{"en":"The company switched from on-premise software to a SaaS solution.","zh-TW":"公司從本地軟體切換到了SaaS解決方案。"},{"en":"SaaS products offer automatic updates and lower upfront costs.","zh-TW":"SaaS產品提供自動更新和更低的前期成本。"}]', '{"full form":"software as a service"}', NULL, 1, 5780, NULL),
(5781, 'sabbatical', '/səˈbætɪkəl/', 'noun', '{"zh-TW":["休假；研究假"],"en":["an extended period of leave granted to an employee for rest or study"]}', NULL, 'sabbatical leave / take a sabbatical / paid sabbatical', '[{"en":"She took a six-month sabbatical to write her book.","zh-TW":"她請了六個月的休假來寫書。"},{"en":"The company offers sabbaticals after ten years of service.","zh-TW":"公司為服務滿十年的員工提供研究假。"}]', '{"adjective":"sabbatical"}', NULL, 4, 5781, NULL),
(5782, 'sacrifice', '/ˈsækrɪfaɪs/', 'noun, verb', '{"zh-TW":["犧牲；獻祭","犧牲；放棄"],"en":["an act of giving up something valued","to give up something important"]}', NULL, 'make a sacrifice / sacrifice for', '[{"en":"She made a great sacrifice for her family.","zh-TW":"她為家人做出了巨大的犧牲。"},{"en":"He sacrificed his career for his children.","zh-TW":"他為了孩子犧牲了自己的事業。"}]', '{"noun":"sacrifice","verb":"sacrifice","adjective":"sacrificial"}', NULL, 3, 5782, NULL),
(5783, 'sad', '/sæd/', 'adjective', '{"zh-TW":["悲傷的；令人遺憾的"],"en":["feeling unhappy","unfortunate"]}', NULL, 'sad news / sadly', '[{"en":"I have sad news about the layoffs.","zh-TW":"我有關於裁員的壞消息。"},{"en":"Sadly, the branch will close.","zh-TW":"不幸的是，分公司將關閉。"}]', '{"adjective":"sad","noun":"sadness","adverb":"sadly","verb":"sadden"}', NULL, 1, 5783, NULL),
(5784, 'safari', '/''səˈfɑːri/', 'noun', '{"zh-TW":["野生動物園之旅；狩獵旅行"],"en":["an overland journey, especially in Africa, to observe wild animals in their natural habitat"]}', NULL, 'go on a safari / wildlife safari / safari park', '[{"en":"They went on a safari in Kenya and saw lions, elephants, and giraffes.","zh-TW":"他們去肯亞參加野生動物觀賞之旅，看到了獅子、大象和長頸鹿。"},{"en":"A guided safari offers the best chance of spotting rare wildlife.","zh-TW":"導覽野生動物旅行提供了發現稀有野生動物的最佳機會。"}]', NULL, NULL, 2, 5784, NULL),
(5785, 'safe', '/seɪf/', 'adjective', '{"zh-TW":["安全的"],"en":["protected from danger"]}', NULL, 'safe and sound / play it safe', '[{"en":"All employees arrived safe and sound.","zh-TW":"所有員工都安全抵達。"},{"en":"Let''s play it safe with this investment.","zh-TW":"這項投資我們保守一點。"}]', '{"adjective":"safe","noun":"safety","adverb":"safely","verb":"safeguard"}', NULL, 1, 5785, NULL),
(5786, 'safe deposit', '/seɪf dɪˈpɒzɪt/', 'noun', '{"zh-TW":["保險箱；安全存款"],"en":["a secure container for valuables in a hotel room"]}', NULL, 'use the safe deposit box / in-room safe deposit', '[{"en":"Please use the safe deposit box for your valuables.","zh-TW":"請使用保險箱存放您的貴重物品。"},{"en":"The safe deposit box is located inside the wardrobe.","zh-TW":"保險箱位於衣櫥內。"}]', NULL, NULL, 4, 5786, NULL),
(5787, 'safeguard', '/ˈseɪfɡɑːrd/', 'noun, verb', '{"zh-TW":["保障措施；防護","保護；防衛"],"en":["a measure taken to protect","to protect from harm"]}', NULL, 'safeguard against / safeguard interests', '[{"en":"We need safeguards against data breaches.","zh-TW":"我們需要防範資料洩露的保障措施。"},{"en":"The policy safeguards employees'' rights.","zh-TW":"該政策保障了員工的權利。"}]', '{"noun":"safeguard","verb":"safeguard"}', NULL, 3, 5787, 929),
(5788, 'safety officer', '/ˈseɪfti ˈɒfɪsər/', 'noun', '{"zh-TW":["安全主任；安全官員"],"en":["a person responsible for managing safety in the workplace"]}', NULL, 'appoint a safety officer / report to the safety officer', '[{"en":"The safety officer conducted the monthly safety inspection.","zh-TW":"安全主任進行了每月安全檢查。"},{"en":"Contact the safety officer if you observe a potential hazard.","zh-TW":"如果您發現潛在危害，請聯繫安全主任。"}]', NULL, NULL, 5, 5788, NULL),
(5789, 'safety stock', '/ˈseɪfti stɒk/', 'noun', '{"zh-TW":["安全庫存"],"en":["extra inventory kept to prevent stockouts due to demand or supply variability"]}', NULL, 'maintain safety stock / safety stock level', '[{"en":"The company maintains a safety stock of 2 weeks of production materials.","zh-TW":"公司維持2週生產材料的安全庫存。"},{"en":"Safety stock acts as a buffer against unexpected supply disruptions.","zh-TW":"安全庫存作為應對意外供應中斷的緩衝。"}]', NULL, NULL, 4, 5789, NULL),
(5790, 'salary', '/ˈsæləri/', 'noun', '{"zh-TW":["薪水；薪資"],"en":["a fixed regular payment for work"]}', NULL, 'annual salary / salary increase / base salary', '[{"en":"Her annual salary is $80,000.","zh-TW":"她的年薪是八萬美元。"},{"en":"Employees received a 5% salary increase.","zh-TW":"員工獲得了5%的加薪。"}]', '{"noun":"salary","adjective":"salaried"}', NULL, 2, 5790, NULL),
(5791, 'salary band', '/ˈsæləri bænd/', 'noun', '{"zh-TW":["薪資範圍；薪酬帶"],"en":["a range of salaries for a particular job grade or level"]}', NULL, 'salary band structure / fall within the salary band', '[{"en":"The new hire''s salary fell within the band for that job grade.","zh-TW":"新員工的薪資在該職等的薪資範圍內。"},{"en":"Transparent salary bands promote fairness across the organization.","zh-TW":"透明的薪資範圍促進了組織內部的公平性。"}]', '{"plural":"salary bands"}', NULL, 4, 5791, NULL),
(5792, 'salary negotiation', '/ˈsæləri nɪˌɡoʊʃiˈeɪʃən/', 'noun', '{"zh-TW":["薪資談判"],"en":["the process of discussing and agreeing on compensation with an employer"]}', NULL, 'salary negotiation tips / enter salary negotiation / successful salary negotiation', '[{"en":"She researched market rates before entering salary negotiation.","zh-TW":"她在進入薪資談判前研究了市場薪資水準。"},{"en":"Salary negotiation is an expected part of the hiring process.","zh-TW":"薪資談判是招聘過程中的預期環節。"}]', '{"verb":"negotiate salary"}', NULL, 5, 5792, NULL),
(5793, 'salary review', '/ˈsæləri rɪˈvjuː/', 'noun', '{"zh-TW":["薪資審查；薪資評估"],"en":["a periodic assessment of an employee compensation level"]}', NULL, 'conduct a salary review / salary review process', '[{"en":"Annual salary reviews are aligned with the company budget cycle.","zh-TW":"年度薪資審查與公司的預算周期相一致。"},{"en":"The salary review resulted in an average 5% increase across the team.","zh-TW":"薪資審查導致整個團隊平均加薪5%。"}]', NULL, NULL, 5, 5793, NULL),
(5794, 'sale', '/seɪl/', 'noun', '{"zh-TW":["銷售；特賣"],"en":["the act of selling","a period when goods are sold at reduced prices"]}', '{"root":{"text":"sale","meaning":"sell (賣)"},"logic":"販售的行為或特賣活動。"}', 'on sale / sales figures / for sale', '[{"en":"The house is for sale.","zh-TW":"這棟房子出售中。"},{"en":"Winter coats are on sale this week.","zh-TW":"冬季外套本週特價。"}]', '{"noun":"salesperson","verb":"sell"}', NULL, 1, 5794, NULL),
(5795, 'sale and leaseback', '/seɪl ænd ˈliːsbæk/', 'noun', '{"zh-TW":["售後回租"],"en":["a transaction in which an owner sells an asset and then leases it back from the buyer"]}', NULL, 'arrange a sale and leaseback / sale and leaseback agreement / benefit from sale and leaseback', '[{"en":"The airline used a sale and leaseback of aircraft to raise immediate cash.","zh-TW":"航空公司使用飛機的售後回租方式來快速籌集現金。"},{"en":"A sale and leaseback allows companies to unlock capital tied up in fixed assets.","zh-TW":"售後回租使公司能夠解放積壓在固定資產中的資本。"}]', NULL, NULL, 5, 5795, NULL),
(5796, 'sales', 'seɪlz', 'noun', '{"zh-TW":["銷售額；銷售量","銷售"],"en":["the total money from selling","the activity of selling"]}', NULL, 'sales target/sales team', '[{"en":"The sales team exceeded its quarterly target.","zh-TW":"銷售團隊超過了季度目標。"}]', '{"verb":"sell","adjective":"sales-oriented"}', NULL, 2, 5796, NULL),
(5797, 'sales budget', '/seɪlz ˈbʌdʒɪt/', 'noun', '{"zh-TW":["銷售預算"],"en":["an estimate of expected sales revenue for a future period"]}', NULL, 'prepare a sales budget / exceed the sales budget', '[{"en":"The sales budget was increased by 20% for the next fiscal year.","zh-TW":"下一財政年度的銷售預算增加了20%。"},{"en":"A realistic sales budget guides hiring and inventory decisions.","zh-TW":"實際的銷售預算指導了聘用和庫存決策。"}]', NULL, NULL, 4, 5797, NULL),
(5798, 'sales conversion rate', '/seɪlz kənˈvɜːrʒən reɪt/', 'noun', '{"zh-TW":["銷售轉換率"],"en":["the percentage of leads or prospects that become actual customers"]}', NULL, 'improve sales conversion rate / track sales conversion rate', '[{"en":"Personalized follow-ups increased the sales conversion rate by 15%.","zh-TW":"個人化的跟進將銷售轉換率提高了15%。"},{"en":"A low sales conversion rate may indicate pricing or messaging issues.","zh-TW":"低銷售轉換率可能表明定價或訊息傳遞存在問題。"}]', NULL, NULL, 5, 5798, NULL),
(5799, 'sales forecast', '/seɪlz ˈfɔːrkæst/', 'noun', '{"zh-TW":["銷售預測"],"en":["an estimate of future sales volume or revenue"]}', NULL, 'prepare a sales forecast / revise the sales forecast', '[{"en":"The sales forecast was revised down after poor August results.","zh-TW":"在八月業績不佳後，銷售預測被下調了。"},{"en":"An accurate sales forecast allows production to be planned effectively.","zh-TW":"準確的銷售預測允許有效規劃生產。"}]', NULL, NULL, 5, 5799, NULL);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(5800, 'sales funnel', '/seɪlz ˈfʌnəl/', 'noun', '{"zh-TW":["銷售漏斗"],"en":["a model representing the stages a customer passes through before buying"]}', NULL, 'top of the funnel / bottom of the funnel / optimize the sales funnel', '[{"en":"Content at the top of the sales funnel builds brand awareness.","zh-TW":"銷售漏斗頂部的內容建立品牌知名度。"},{"en":"The sales funnel revealed high drop-off at the pricing stage.","zh-TW":"銷售漏斗顯示在定價階段的高流失率。"}]', NULL, NULL, 4, 5800, NULL),
(5801, 'sales ledger', '/seɪlz ˈledʒər/', 'noun', '{"zh-TW":["銷售分類帳；應收帳款總帳"],"en":["a record of all sales transactions and amounts owed by customers"]}', NULL, 'update the sales ledger / sales ledger reconciliation', '[{"en":"The accounts team reconciles the sales ledger with bank receipts.","zh-TW":"帳務團隊將銷售分類帳與銀行收款對帳。"},{"en":"An accurate sales ledger is essential for tracking receivables.","zh-TW":"準確的銷售分類帳對於追蹤應收帳款至關重要。"}]', NULL, NULL, 4, 5801, NULL),
(5802, 'sales pipeline', '/seɪlz ˈpaɪplaɪn/', 'noun', '{"zh-TW":["銷售管道；業務流水線"],"en":["the progression of potential deals a sales team is working on"]}', NULL, 'build a sales pipeline / manage the sales pipeline', '[{"en":"The sales pipeline shows deals worth 5 million in the next quarter.","zh-TW":"銷售管道顯示下個季度有價值500萬元的交易。"},{"en":"Regular pipeline reviews identify stalled opportunities.","zh-TW":"定期管道審查識別了停滯的商機。"}]', NULL, NULL, 5, 5802, NULL),
(5803, 'sales quota', '/seɪlz ˈkwoʊtə/', 'noun', '{"zh-TW":["銷售配額"],"en":["a target amount of sales that a salesperson is expected to achieve in a period"]}', NULL, 'meet sales quota / sales quota attainment', '[{"en":"The sales team achieved 110% of their sales quota for the quarter.","zh-TW":"銷售團隊實現了本季度銷售配額的110%。"},{"en":"Sales quotas are set based on market potential and historical performance.","zh-TW":"銷售配額根據市場潛力和歷史業績設定。"}]', NULL, NULL, 4, 5803, NULL),
(5804, 'sales representative', '/seɪlz ˌrɛprɪˈzɛntətɪv/', 'noun', '{"zh-TW":["業務代表；銷售代表"],"en":["a person employed to sell goods or services"]}', NULL, 'contact a sales representative / field sales representative', '[{"en":"The sales representative visited three clients this week.","zh-TW":"業務代表本週拜訪了三位客戶。"},{"en":"A skilled sales representative builds long-term client relationships.","zh-TW":"熟練的業務代表建立了長期的客戶關係。"}]', NULL, NULL, 5, 5804, NULL),
(5805, 'sales target', '/seɪlz ˈtɑːrɡɪt/', 'noun', '{"zh-TW":["銷售目標"],"en":["the desired level of sales for a specific period"]}', NULL, 'meet the sales target / set sales targets', '[{"en":"The team met its quarterly sales target ahead of schedule.","zh-TW":"團隊提前完成了季度銷售目標。"},{"en":"Incentives are offered for exceeding the annual sales target.","zh-TW":"超過年度銷售目標可獲得獎勵。"}]', NULL, NULL, 4, 5805, NULL),
(5806, 'sales territory', '/seɪlz ˈterɪtɔːri/', 'noun', '{"zh-TW":["銷售區域"],"en":["a defined geographic area assigned to a sales representative"]}', NULL, 'assign a sales territory / cover a sales territory', '[{"en":"Each sales rep is responsible for a specific sales territory.","zh-TW":"每位銷售代表負責特定的銷售區域。"},{"en":"Expanding sales territories is a sign of business growth.","zh-TW":"擴大銷售區域是業務增長的標誌。"}]', NULL, NULL, 5, 5806, NULL),
(5807, 'salient', '/ˈseɪliənt/', 'adjective', '{"zh-TW":["顯著的；突出的"],"en":["most noticeable or important; prominent"]}', NULL, 'salient feature / salient point / salient fact', '[{"en":"The most salient finding is the gap between theory and practice.","zh-TW":"最顯著的發現是理論與實踐之間的差距。"},{"en":"Highlight the salient points in your summary.","zh-TW":"在摘要中突出顯著的要點。"}]', '{"adverb":"saliently","noun":"salience"}', NULL, 3, 5807, NULL),
(5808, 'salvage value', '/ˈsælvɪdʒ ˈvæljuː/', 'noun', '{"zh-TW":["殘值；清算價值"],"en":["the expected amount recoverable from an asset at the end of its useful life"]}', NULL, 'estimate salvage value / salvage value calculation', '[{"en":"The plant was depreciated to its estimated salvage value of $10000.","zh-TW":"工廠被折舊到估計殘值10,000元。"},{"en":"A higher salvage value reduces the annual depreciation charge.","zh-TW":"較高的殘值降低了年度折舊費用。"}]', '{"synonym":"residual value"}', NULL, 5, 5808, NULL),
(5809, 'sample', '/ˈsæmpl/', 'noun, verb', '{"zh-TW":["樣品；樣本","取樣；品嚐"],"en":["a small part representing the whole","to take a sample of"]}', NULL, 'free sample / sample size / random sample', '[{"en":"We collected a random sample of 500 customers.","zh-TW":"我們隨機抽樣了500位顧客。"},{"en":"Would you like to sample the new product?","zh-TW":"您想試用新產品嗎？"}]', '{"noun":"sample, sampling","verb":"sample"}', NULL, 2, 5809, NULL),
(5810, 'sampling method', '/ˈsɑːmplɪŋ ˈmeθəd/', 'noun', '{"zh-TW":["抽樣方法"],"en":["a technique for selecting a subset of a population for research or analysis"]}', NULL, 'apply a sampling method / random sampling method', '[{"en":"A stratified sampling method was used to ensure representative survey results.","zh-TW":"使用了分層抽樣方法以確保代表性的調查結果。"},{"en":"The sampling method must be documented for audit purposes.","zh-TW":"抽樣方法必須為審計目的而記錄在案。"}]', NULL, NULL, 5, 5810, NULL),
(5811, 'sanction', '/ˈsæŋkʃən/', 'noun', '{"zh-TW":["制裁；許可","制裁；處罰","批准；認可"],"en":["a penalty imposed on a country; official approval","a penalty for breaking a law","to give official permission"]}', NULL, 'economic sanctions / impose sanctions; impose sanctions / economic sanctions / lift sanctions', '[{"en":"The country faces economic sanctions.","zh-TW":"該國面臨經濟制裁。"},{"en":"Sanctions were imposed on the regime.","zh-TW":"對該政權實施了制裁。"},{"en":"The government imposed economic sanctions.","zh-TW":"政府實施了經濟制裁。"},{"en":"The plan was sanctioned by the board.","zh-TW":"該計畫已獲董事會批准。"}]', '{"verb":"sanction","noun":"sanction"}', NULL, 3, 5811, 930),
(5812, 'sanctions', '/ˈsæŋkʃənz/', 'noun', '{"zh-TW":["制裁；處罰"],"en":["penalties imposed by governments on other countries or entities"]}', NULL, 'impose sanctions / lift sanctions / economic sanctions', '[{"en":"Economic sanctions were imposed on the country for treaty violations.","zh-TW":"因違反條約，對該國實施了經濟制裁。"},{"en":"Sanctions disrupted the company''s ability to do business abroad.","zh-TW":"制裁干擾了公司在海外的業務能力。"}]', '{"verb":"sanction","singular":"sanction"}', NULL, 3, 5812, NULL),
(5813, 'satellite', '/ˈsætəlaɪt/', 'noun', '{"zh-TW":["衛星"],"en":["an object orbiting a planet; a device in space"]}', NULL, 'satellite TV / communication satellite', '[{"en":"The satellite orbits the Earth.","zh-TW":"衛星繞地球運行。"},{"en":"We get internet via satellite.","zh-TW":"我們透過衛星上網。"}]', NULL, NULL, 3, 5813, NULL),
(5814, 'satire', '/ˈsætaɪər/', 'noun', '{"zh-TW":["諷刺；諷刺文學"],"en":["the use of humor, irony, or exaggeration to criticize or expose foolishness"]}', NULL, 'political satire / social satire / biting satire', '[{"en":"The comedy show uses satire to challenge politicians and media.","zh-TW":"這個喜劇節目使用諷刺來挑戰政客和媒體。"},{"en":"Satire has been a powerful tool for social criticism throughout history.","zh-TW":"諷刺在歷史上一直是社會批評的有力工具。"}]', '{"adjective":"satirical","adverb":"satirically","verb":"satirize"}', NULL, 2, 5814, NULL),
(5815, 'satisfy', '/ˈsætɪsfaɪ/', 'verb', '{"zh-TW":["滿足；使滿意","符合（要求）"],"en":["to fulfill the needs or desires of","to meet requirements"]}', '{"suffix":{"text":"-fy","meaning":"使..."}}', 'satisfy demands / satisfy customers / satisfy requirements', '[{"en":"The results satisfied all stakeholders.","zh-TW":"結果讓所有利害關係人都滿意。"},{"en":"The candidate satisfies all the requirements.","zh-TW":"這位候選人符合所有要求。"}]', '{"noun":"satisfaction","verb":"satisfy","adjective":"satisfactory, satisfied, satisfying"}', NULL, 3, 5815, NULL),
(5816, 'saturated fat', '/''sætʃəreɪtɪd fæt/', 'noun', '{"zh-TW":["飽和脂肪"],"en":["a type of fat found mainly in animal products that is solid at room temperature and can raise cholesterol levels"]}', NULL, 'reduce saturated fat / high in saturated fat / saturated fat content', '[{"en":"Butter, cheese, and red meat are high in saturated fat.","zh-TW":"奶油、起司和紅肉富含飽和脂肪。"},{"en":"Health guidelines recommend limiting saturated fat intake to protect heart health.","zh-TW":"健康指南建議限制飽和脂肪攝取以保護心臟健康。"}]', NULL, NULL, 5, 5816, NULL),
(5817, 'sauna', '/ˈsɔːnə/', 'noun', '{"zh-TW":["桑拿浴室；三溫暖"],"en":["a room heated to a high temperature for relaxation"]}', NULL, 'use the sauna / hotel sauna', '[{"en":"The hotel''s sauna is open from 6 am to 10 pm.","zh-TW":"飯店的三溫暖從早上6點開放至晚上10點。"},{"en":"A sauna session can help you relax after a long flight.","zh-TW":"桑拿浴有助於長途飛行後放鬆。"}]', NULL, NULL, 2, 5817, NULL),
(5818, 'sauté', '/''soʊteɪ/', 'verb', '{"zh-TW":["煎炒；嫩煎"],"en":["to fry food quickly in a small amount of hot fat"]}', NULL, 'sauté in butter / sauté until golden / sauté vegetables', '[{"en":"Sauté the onions in olive oil until they are translucent and soft.","zh-TW":"在橄欖油中煎炒洋蔥，直到它們透明柔軟。"},{"en":"She sautéed the mushrooms with garlic and fresh thyme.","zh-TW":"她用大蒜和新鮮百里香煎炒了蘑菇。"}]', NULL, NULL, 2, 5818, NULL),
(5819, 'save', '/seɪv/', 'verb', '{"zh-TW":["節省；儲蓄","拯救；保存"],"en":["to keep money for future use","to rescue from danger"]}', NULL, 'save money / save time / save energy', '[{"en":"She saves 20% of her income every month.","zh-TW":"她每個月存下收入的20%。"},{"en":"The new system saves us a lot of time.","zh-TW":"新系統為我們節省了大量時間。"}]', '{"noun":"savings, saver","verb":"save"}', NULL, 1, 5819, NULL),
(5820, 'savings account', '/ˈseɪvɪŋz əˈkaʊnt/', 'noun', '{"zh-TW":["儲蓄帳戶"],"en":["a bank account that earns interest on deposits"]}', NULL, 'open a savings account / savings account interest rate', '[{"en":"Opening a savings account is the first step to financial security.","zh-TW":"開設儲蓄帳戶是財務安全的第一步。"},{"en":"The savings account offered a competitive interest rate.","zh-TW":"該儲蓄帳戶提供了有競爭力的利率。"}]', NULL, NULL, 5, 5820, NULL),
(5821, 'savory', '/''seɪvəri/', 'adjective', '{"zh-TW":["鹹味的；美味的"],"en":["belonging to the category of food that is salty or spicy rather than sweet"]}', NULL, 'savory dish / savory snack / savory flavor', '[{"en":"She preferred savory snacks like nuts and cheese over sweet ones.","zh-TW":"她更喜歡堅果和起司等鹹味零食而非甜食。"},{"en":"The savory pie was filled with chicken, mushrooms, and herbs.","zh-TW":"這個鹹味派裡填充著雞肉、蘑菇和香草。"}]', NULL, NULL, 2, 5821, NULL),
(5822, 'say', 'seɪ', 'verb', '{"zh-TW":["說；表示","聲稱"],"en":["to speak words","to express in words"]}', NULL, 'say something/that', '[{"en":"What did the manager say?","zh-TW":"經理說了什麼？"}]', '{"noun":"saying"}', NULL, 1, 5822, NULL),
(5823, 'scalability', '/ˌskeɪləˈbɪlɪti/', 'noun', '{"zh-TW":["可擴展性；擴展能力"],"en":["the ability of a system or business to grow efficiently"]}', NULL, 'business scalability / scalability of the model', '[{"en":"The platform was designed with scalability in mind.","zh-TW":"該平台設計時考慮了可擴展性。"},{"en":"Scalability is essential for any startup aiming to grow.","zh-TW":"可擴展性對任何目標成長的新創公司都至關重要。"}]', '{"adjective":"scalable","verb":"scale"}', NULL, 4, 5823, 810),
(5824, 'scalable', '/ˈskeɪləbl/', 'adjective', '{"zh-TW":["可擴展的；可規模化的"],"en":["able to grow or expand efficiently to meet increasing demand"]}', NULL, 'scalable business model / scalable solution / highly scalable', '[{"en":"The SaaS platform is highly scalable and can handle millions of users.","zh-TW":"SaaS平台具有高度可擴展性，可以處理數百萬用戶。"},{"en":"Investors seek scalable business models with large addressable markets.","zh-TW":"投資者尋求具有大型可觸達市場的可擴展商業模式。"}]', '{"noun":"scalability","verb":"scale"}', NULL, 3, 5824, NULL),
(5825, 'scalable architecture', '/ˈskeɪləbəl ˈɑːrkɪˌtekʧər/', 'noun', '{"zh-TW":["可擴展架構"],"en":["a system design that can handle increasing workloads by adding resources without redesigning the core structure"]}', NULL, 'design a scalable architecture / build a scalable architecture / scalable architecture pattern', '[{"en":"The engineering team built a scalable architecture that could support millions of users.","zh-TW":"工程團隊構建了一個可以支持數百萬用戶的可擴展架構。"},{"en":"A scalable architecture is essential for startups expecting rapid growth.","zh-TW":"對於預期快速增長的初創公司來說，可擴展架構至關重要。"}]', NULL, NULL, 5, 5825, NULL),
(5826, 'scalable solution', '/ˈskeɪləbəl səˈluːʃən/', 'noun', '{"zh-TW":["可擴展的解決方案"],"en":["a solution that can grow or adapt as demand or scope increases"]}', NULL, 'implement a scalable solution / design a scalable solution', '[{"en":"The company chose a cloud-based, scalable solution for its data needs.","zh-TW":"公司選擇了一個基於雲端的可擴展解決方案來滿足其數據需求。"},{"en":"A scalable solution prevents the need for costly system replacements.","zh-TW":"可擴展的解決方案防止了昂貴的系統更換需求。"}]', '{"adjective":"scalable"}', NULL, 5, 5826, NULL),
(5827, 'scale', '/skeɪl/', 'noun, verb', '{"zh-TW":["規模；比例","擴大規模；攀登"],"en":["the size or extent of something","to increase in size"]}', NULL, 'on a large scale / economies of scale / scale up', '[{"en":"The company plans to scale up production.","zh-TW":"公司計劃擴大生產規模。"},{"en":"The project was carried out on a large scale.","zh-TW":"該專案是大規模進行的。"}]', '{"noun":"scale","verb":"scale","adjective":"scalable"}', NULL, 2, 5827, NULL),
(5828, 'scale up', '/skeɪl ʌp/', 'verb', '{"zh-TW":["擴大規模；向上擴展"],"en":["to increase the size or capacity of a business or operation"]}', NULL, 'scale up production / scale up operations', '[{"en":"The startup scaled up quickly after receiving the Series B investment.","zh-TW":"新創公司在獲得B輪投資後迅速擴大了規模。"},{"en":"Scaling up requires more staff, systems, and financial resources.","zh-TW":"擴大規模需要更多的員工、系統和財務資源。"}]', '{"noun":"scale-up","adjective":"scaled up"}', NULL, 3, 5828, NULL),
(5829, 'scan', '/skæn/', 'verb, noun', '{"zh-TW":["掃描；瀏覽","掃描"],"en":["to examine quickly","a medical or electronic examination"]}', NULL, 'scan a document / brain scan / scan for errors', '[{"en":"Please scan the document and email it.","zh-TW":"請掃描文件並用電子郵件發送。"},{"en":"She scanned the report for key findings.","zh-TW":"她快速瀏覽了報告的主要發現。"}]', '{"noun":"scan, scanner","verb":"scan"}', NULL, 1, 5829, NULL),
(5830, 'scarce', '/skers/', 'adjective', '{"zh-TW":["稀少的；缺乏的"],"en":["insufficient for the demand; not enough"]}', NULL, 'scarce resources / increasingly scarce', '[{"en":"Clean water is scarce in many regions.","zh-TW":"乾淨的水在許多地區很稀缺。"},{"en":"Skilled workers are becoming increasingly scarce.","zh-TW":"技術工人越來越稀缺。"}]', '{"noun":"scarcity","adjective":"scarce","adverb":"scarcely"}', NULL, 2, 5830, NULL),
(5831, 'scarcity', '/ˈskeərsɪti/', 'noun', '{"zh-TW":["稀缺；稀缺性"],"en":["the limited availability of a resource relative to demand"]}', NULL, 'scarcity of resources / create scarcity / scarcity principle', '[{"en":"Scarcity of skilled engineers pushed salaries higher.","zh-TW":"技術工程師的稀缺推高了薪資。"},{"en":"The marketing campaign used scarcity to drive urgency.","zh-TW":"行銷活動利用稀缺性製造緊迫感。"}]', '{"adjective":"scarce","adverb":"scarcely"}', NULL, 3, 5831, NULL),
(5832, 'scenario', '/sɪˈnærioʊ/', 'noun', '{"zh-TW":["情境；劇本","可能的情況"],"en":["a possible sequence of events","a written outline of a story"]}', NULL, 'worst-case scenario / best-case scenario / likely scenario', '[{"en":"In the worst-case scenario, we lose 10% revenue.","zh-TW":"在最壞的情況下，我們會損失10%的收入。"},{"en":"Let''s consider various scenarios before deciding.","zh-TW":"讓我們在決定前考慮各種情境。"}]', '{"noun":"scenario"}', NULL, 3, 5832, NULL),
(5833, 'scenario analysis', '/sɪˈnɑːriəʊ əˈnæləsɪs/', 'noun', '{"zh-TW":["情景分析"],"en":["an assessment of possible future events and their implications"]}', NULL, 'conduct scenario analysis / scenario analysis approach / climate scenario analysis', '[{"en":"Scenario analysis prepares businesses for a range of possible futures.","zh-TW":"情景分析為企業應對各種可能的未來做準備。"},{"en":"The bank used scenario analysis to test its capital adequacy under stress conditions.","zh-TW":"銀行使用情景分析來測試壓力條件下的資本充足性。"}]', NULL, NULL, 5, 5833, NULL),
(5834, 'scenario planning', '/sɪˈneərioʊ ˈplænɪŋ/', 'noun', '{"zh-TW":["情境規劃"],"en":["a strategic planning method involving multiple future scenarios"]}', NULL, 'conduct scenario planning / scenario planning exercise', '[{"en":"The executive team used scenario planning to prepare for economic downturns.","zh-TW":"執行團隊使用情境規劃為經濟低迷做準備。"},{"en":"Scenario planning helps organizations respond flexibly to uncertainty.","zh-TW":"情境規劃幫助組織靈活應對不確定性。"}]', NULL, NULL, 5, 5834, NULL),
(5835, 'scenic', '/''siːnɪk/', 'adjective', '{"zh-TW":["風景優美的；景色宜人的"],"en":["providing or relating to views of impressive or beautiful natural scenery"]}', NULL, 'scenic route / scenic view / scenic drive', '[{"en":"We took the scenic route along the coast instead of the highway.","zh-TW":"我們走了沿海岸的風景路線，而不是高速公路。"},{"en":"The scenic overlook gave a panoramic view of the valley below.","zh-TW":"這個風景俯瞰點可以看到下方山谷的全景。"}]', '{"noun":"scenery"}', NULL, 2, 5835, NULL),
(5836, 'scenic flight', '/''siːnɪk flaɪt/', 'noun', '{"zh-TW":["觀光飛行；風景直升機遊覽"],"en":["a short flight taken primarily for the view rather than transportation"]}', NULL, 'take a scenic flight / book a scenic flight / scenic flight over', '[{"en":"She booked a scenic flight over the Grand Canyon for a bird''s-eye view.","zh-TW":"她預訂了一次在大峽谷上空的觀光飛行，以便欣賞鳥瞰景色。"},{"en":"A scenic flight at dawn offers the most spectacular views of the mountains.","zh-TW":"黎明時的觀光飛行提供了最壯觀的山脈景色。"}]', NULL, NULL, 5, 5836, NULL),
(5837, 'scenic overlook', '/''siːnɪk ˌəʊvəlʊk/', 'noun', '{"zh-TW":["觀景台；景觀瞭望點"],"en":["a designated area alongside a road providing a view of the surrounding landscape"]}', NULL, 'park at the scenic overlook / visit a scenic overlook', '[{"en":"The scenic overlook offered a breathtaking view of the valley below.","zh-TW":"觀景台提供了下方山谷令人嘆為觀止的景色。"},{"en":"Tourists stop at the scenic overlook to take photographs of the mountain range.","zh-TW":"遊客在觀景台停下來拍攝山脈的照片。"}]', NULL, NULL, 5, 5837, NULL),
(5838, 'scenic route', '/''siːnɪk ruːt/', 'noun', '{"zh-TW":["風景路線；景觀道路"],"en":["a longer, more picturesque route as opposed to the fastest or most direct one"]}', NULL, 'take the scenic route / follow the scenic route / recommend the scenic route', '[{"en":"We took the scenic route along the mountain ridge for breathtaking views.","zh-TW":"我們沿著山脊走風景路線，欣賞令人嘆為觀止的景色。"},{"en":"The scenic route added an hour to our journey but was well worth it.","zh-TW":"風景路線讓我們的旅程多了一個小時，但非常值得。"}]', NULL, NULL, 4, 5838, NULL),
(5839, 'schedule', '/ˈskedʒuːl/', 'noun, verb', '{"zh-TW":["時間表；計畫表","安排；排定"],"en":["a plan of activities or events","to arrange for something to happen"]}', NULL, 'on schedule / behind schedule / ahead of schedule', '[{"en":"The project is on schedule.","zh-TW":"專案如期進行。"},{"en":"The meeting has been scheduled for Monday.","zh-TW":"會議已排定在週一。"}]', '{"noun":"schedule, scheduling","verb":"schedule, reschedule","adjective":"scheduled, unscheduled"}', NULL, 3, 5839, 61),
(5840, 'scheme', '/skiːm/', 'noun, verb', '{"zh-TW":["計畫；方案","策劃；圖謀"],"en":["a systematic plan or arrangement","to make plans secretly"]}', NULL, 'color scheme / pension scheme / scheme to do sth.', '[{"en":"The company launched a new training scheme.","zh-TW":"公司推出了新的培訓方案。"},{"en":"They schemed to take over the business.","zh-TW":"他們密謀接管這家公司。"}]', '{"noun":"scheme, schemer","verb":"scheme"}', NULL, 2, 5840, NULL),
(5841, 'scholarship', '/ˈskɒlərʃɪp/', 'noun', '{"zh-TW":["獎學金"],"en":["money given to a student for their education"]}', NULL, 'win a scholarship / full scholarship', '[{"en":"She won a full scholarship.","zh-TW":"她獲得了全額獎學金。"},{"en":"Apply for scholarships early.","zh-TW":"要早點申請獎學金。"}]', '{"noun2":"scholar"}', NULL, 4, 5841, NULL),
(5842, 'scholastic', '/skəˈlæstɪk/', 'adjective', '{"zh-TW":["學術的；學業的"],"en":["of or concerning schools and education"]}', NULL, 'scholastic achievement / scholastic aptitude / scholastic record', '[{"en":"Her scholastic achievements earned her a prestigious scholarship.","zh-TW":"她的學業成就為她贏得了一份享有盛譽的獎學金。"},{"en":"The program aims to improve scholastic performance in underserved communities.","zh-TW":"該計畫旨在提升弱勢社區的學業表現。"}]', '{"noun":"scholarship","adverb":"scholastically"}', NULL, 4, 5842, NULL),
(5843, 'school', '/skuːl/', 'noun', '{"zh-TW":["學校"],"en":["an institution for educating children"]}', NULL, 'business school / school of thought', '[{"en":"He graduated from a top business school.","zh-TW":"他從頂尖商學院畢業。"},{"en":"There are two schools of thought on this.","zh-TW":"對此有兩種學派觀點。"}]', '{"noun":"school","noun2":"schooling"}', NULL, 2, 5843, NULL),
(5844, 'science', '/ˈsaɪəns/', 'noun', '{"zh-TW":["科學"],"en":["the study of the natural world through observation"]}', NULL, 'data science / computer science', '[{"en":"Data science drives our decisions.","zh-TW":"數據科學驅動我們的決策。"},{"en":"She has a degree in computer science.","zh-TW":"她有電腦科學學位。"}]', '{"noun":"science","noun2":"scientist","adjective":"scientific","adverb":"scientifically"}', NULL, 3, 5844, NULL),
(5845, 'science fair', '/''saɪəns feər/', 'noun', '{"zh-TW":["科學博覽會；科學展示會"],"en":["a competition or exhibition where students present their science projects"]}', NULL, 'enter a science fair / win a science fair / participate in a science fair', '[{"en":"She won first place at the regional science fair with her water purification project.","zh-TW":"她憑藉水淨化項目在地區科學博覽會上獲得了第一名。"},{"en":"The science fair inspired young students to pursue careers in research.","zh-TW":"科學博覽會激勵年輕學生追求研究職業。"}]', NULL, NULL, 4, 5845, NULL),
(5846, 'scope', '/skoʊp/', 'noun', '{"zh-TW":["範圍；領域","機會；餘地"],"en":["the range of a subject or activity","opportunity for action"]}', NULL, 'scope of work / beyond the scope / within scope', '[{"en":"This issue is beyond the scope of our project.","zh-TW":"這個問題超出了我們專案的範圍。"},{"en":"There is scope for improvement.","zh-TW":"仍有改進的空間。"}]', '{"noun":"scope"}', NULL, 2, 5846, NULL),
(5847, 'scope creep', '/skoʊp kriːp/', 'noun', '{"zh-TW":["範疇蔓延"],"en":["the gradual expansion of a project''s scope beyond its original boundaries"]}', NULL, 'prevent scope creep / manage scope creep / identify scope creep', '[{"en":"Scope creep caused the project to miss its deadline.","zh-TW":"範疇蔓延導致項目錯過了截止日期。"},{"en":"A change control process helps prevent scope creep.","zh-TW":"變更控制流程有助於防止範疇蔓延。"}]', NULL, NULL, 4, 5847, NULL),
(5848, 'scope of work', '/skoʊp əv wɜːrk/', 'noun', '{"zh-TW":["工作範圍"],"en":["a document describing all the tasks, deliverables, and timelines for a project"]}', NULL, 'define scope of work / scope of work agreement', '[{"en":"The scope of work was agreed upon and signed before the project started.","zh-TW":"工作範圍在項目開始前已達成協議並簽署。"},{"en":"Changes outside the scope of work may incur additional charges.","zh-TW":"工作範圍以外的更改可能會產生額外費用。"}]', NULL, NULL, 5, 5848, NULL),
(5849, 'score', '/skɔːr/', 'noun', '{"zh-TW":["得分；分數"],"en":["the number of points in a game"]}', NULL, 'final score / high score', '[{"en":"The final score was 3-2.","zh-TW":"最終比分是3比2。"},{"en":"She got a high score on the test.","zh-TW":"她考試得了高分。"}]', '{"verb":"score","noun2":"scoreboard"}', NULL, 2, 5849, NULL);
