(5850, 'scoreboard', '/''skɔːrbɔːrd/', 'noun', '{"zh-TW":["記分板；計分牌"],"en":["a large board or electronic display showing the current score in a game or competition"]}', NULL, 'check the scoreboard / scoreboard update / lead on the scoreboard', '[{"en":"With five minutes remaining, the scoreboard showed a tie.","zh-TW":"距比賽結束還有五分鐘，記分板顯示平局。"},{"en":"The crowd cheered as the home team''s score appeared on the scoreboard.","zh-TW":"當主隊的得分出現在記分板上時，觀眾歡呼雀躍。"}]', NULL, NULL, 4, 5850, NULL),
(5851, 'scorecard', '/ˈskɔːrkɑːrd/', 'noun', '{"zh-TW":["計分卡；績效記分卡"],"en":["a report summarizing performance across key metrics"]}', NULL, 'balanced scorecard / performance scorecard / update the scorecard', '[{"en":"The balanced scorecard tracks financial and non-financial performance.","zh-TW":"平衡計分卡追蹤財務和非財務績效。"},{"en":"The weekly scorecard is shared with all department heads.","zh-TW":"週報計分卡分享給所有部門主管。"}]', NULL, NULL, 3, 5851, NULL),
(5852, 'screen', '/skriːn/', 'noun, verb', '{"zh-TW":["螢幕；屏幕","篩選；審查"],"en":["a display surface","to examine or check systematically"]}', NULL, 'screen candidates / on screen / screening process', '[{"en":"All applicants are screened before the interview.","zh-TW":"所有應徵者在面試前都會經過篩選。"},{"en":"The presentation will appear on screen.","zh-TW":"簡報將顯示在螢幕上。"}]', '{"noun":"screen, screening","verb":"screen"}', NULL, 2, 5852, NULL),
(5853, 'screening', '/ˈskriːnɪŋ/', 'noun', '{"zh-TW":["篩選；審查","放映"],"en":["the testing or examining of a group","the showing of a film"]}', NULL, 'background screening / screening process / health screening', '[{"en":"All candidates undergo a background screening.","zh-TW":"所有候選人都會接受背景審查。"},{"en":"The screening process takes about two weeks.","zh-TW":"篩選過程大約需要兩週。"}]', '{"noun":"screening, screen","verb":"screen"}', NULL, 3, 5853, NULL),
(5854, 'Scrum', '/skrʌm/', 'noun', '{"zh-TW":["Scrum框架；敏捷開發框架"],"en":["an agile framework for managing and completing complex projects"]}', NULL, 'Scrum framework / Scrum master / Scrum team / daily Scrum', '[{"en":"The development team adopted Scrum to improve delivery speed.","zh-TW":"開發團隊採用Scrum框架以提高交付速度。"},{"en":"The daily Scrum is a 15-minute standup meeting.","zh-TW":"每日Scrum是一個15分鐘的站立會議。"}]', '{"noun":"Scrum master"}', NULL, 2, 5854, NULL),
(5855, 'scrupulous', '/''skruːpjʊləs/', 'adjective', '{"zh-TW":["謹慎的；一絲不苟的"],"en":["careful to do the right thing; very concerned with moral standards or precise accuracy"]}', NULL, 'scrupulous attention / scrupulous conduct / scrupulous honesty', '[{"en":"She maintained scrupulous records of all financial transactions for the audit.","zh-TW":"她為審計維護了所有財務交易的一絲不苟的記錄。"},{"en":"His scrupulous attention to contract details prevented many potential disputes.","zh-TW":"他對合同細節的謹慎關注防止了許多潜在糾紛。"}]', '{"adverb":"scrupulously","noun":"scrupulousness"}', NULL, 4, 5855, NULL),
(5856, 'scrutiny', '/ˈskruːtəni/', 'noun', '{"zh-TW":["仔細檢查；審查"],"en":["careful and thorough examination"]}', NULL, 'under scrutiny / public scrutiny / close scrutiny', '[{"en":"The company''s finances are under close scrutiny.","zh-TW":"公司的財務正在接受仔細審查。"},{"en":"His actions came under public scrutiny.","zh-TW":"他的行為受到了公眾的審視。"}]', '{"noun":"scrutiny","verb":"scrutinize"}', NULL, 3, 5856, NULL),
(5857, 'sculpture', '/ˈskʌlptʃər/', 'noun', '{"zh-TW":["雕塑"],"en":["a three-dimensional work of art"]}', '{"root":{"text":"sculpt","meaning":"carve (雕刻)"},"suffix":{"text":"-ure","meaning":"result (結果)"},"logic":"雕刻的結果，即「雕塑」。"}', 'marble sculpture / modern sculpture', '[{"en":"The sculpture was made entirely of recycled metal.","zh-TW":"這座雕塑完全由回收金屬製成。"},{"en":"There is a famous sculpture in the park.","zh-TW":"公園裡有一座著名的雕塑。"}]', '{"verb":"sculpt","noun":"sculptor"}', NULL, 3, 5857, NULL),
(5858, 'sea', '/siː/', 'noun', '{"zh-TW":["海"],"en":["a large body of saltwater"]}', NULL, 'by sea / at sea', '[{"en":"Goods are shipped by sea.","zh-TW":"貨物經由海運運送。"},{"en":"I am still at sea about the new policy.","zh-TW":"我對新政策還摸不著頭緒。"}]', '{"noun":"sea","adjective":"seaside","noun2":"seaport"}', NULL, 1, 5858, NULL),
(5859, 'sea freight', '/siː freɪt/', 'noun', '{"zh-TW":["海運貨物"],"en":["goods transported by sea"]}', NULL, 'ship by sea freight / sea freight schedule', '[{"en":"Sea freight is more economical for large shipments.","zh-TW":"海運對大宗貨物更為經濟。"},{"en":"The sea freight arrived on schedule with no damage.","zh-TW":"海運貨物按時到達，無損壞。"}]', NULL, NULL, 4, 5859, NULL),
(5860, 'sea level rise', '/siː ˈlɛvəl raɪz/', 'noun', '{"zh-TW":["海平面上升"],"en":["the increase in ocean levels caused by melting ice and warming"]}', NULL, 'address sea level rise / impact of sea level rise', '[{"en":"Sea level rise threatens coastal cities around the world.","zh-TW":"海平面上升威脅著世界各地的沿海城市。"},{"en":"Climate action is urgently needed to slow sea level rise.","zh-TW":"迫切需要氣候行動來減緩海平面上升。"}]', NULL, NULL, 5, 5860, NULL),
(5861, 'search engine optimization', '/sɜːrtʃ ˈendʒɪn ˌɒptɪmaɪˈzeɪʃən/', 'noun', '{"zh-TW":["搜尋引擎優化"],"en":["techniques to improve a website ranking in organic search results"]}', NULL, 'invest in search engine optimization / search engine optimization strategy', '[{"en":"Search engine optimization increased organic traffic by 80%.","zh-TW":"搜尋引擎優化使自然流量增加了80%。"},{"en":"Content quality is the most important factor in search engine optimization.","zh-TW":"內容品質是搜尋引擎優化中最重要的因素。"}]', '{"abbreviation":"SEO"}', NULL, 5, 5861, NULL),
(5862, 'season', '/ˈsiːzən/', 'noun', '{"zh-TW":["季節；賽季"],"en":["one of the four periods of the year"]}', NULL, 'in season / off season', '[{"en":"Winter is my favorite season.","zh-TW":"冬天是我最喜歡的季節。"},{"en":"The team had a great season.","zh-TW":"這支球隊賽季表現出色。"}]', '{"adjective":"seasonal"}', NULL, 2, 5862, NULL),
(5863, 'seasonal demand', '/ˈsiːzənl dɪˈmɑːnd/', 'noun', '{"zh-TW":["季節性需求"],"en":["fluctuation in demand for a product or service based on the time of year"]}', NULL, 'manage seasonal demand / peak seasonal demand', '[{"en":"Retailers hire extra staff to manage seasonal demand during holidays.","zh-TW":"零售商在假期期間聘用額外員工來管理季節性需求。"},{"en":"Seasonal demand forecasting helps optimize inventory and staffing.","zh-TW":"季節性需求預測有助於優化庫存和人員配置。"}]', NULL, NULL, 5, 5863, NULL),
(5864, 'seasoning', '/ˈsiːzənɪŋ/', 'noun', '{"zh-TW":["調味料；調味"],"en":["salt, herbs, or spices added to food"]}', NULL, 'add seasoning / light seasoning', '[{"en":"The chef adjusted the seasoning before serving.","zh-TW":"主廚在上菜前調整了調味。"},{"en":"This dish requires very little seasoning.","zh-TW":"這道菜只需要很少的調味料。"}]', '{"verb":"season","adjective":"seasoned"}', NULL, 3, 5864, NULL),
(5865, 'seat', '/siːt/', 'noun', '{"zh-TW":["座位"],"en":["a place to sit"]}', NULL, 'take a seat / window seat', '[{"en":"Please take a seat.","zh-TW":"請坐。"},{"en":"I prefer a window seat on flights.","zh-TW":"搭飛機時我偏好靠窗的座位。"}]', '{"noun":"seat","verb":"seat","noun2":"seating"}', NULL, 1, 5865, NULL),
