(5867, 'secondary market', '/ˈsekəndri ˈmɑːrkɪt/', 'noun', '{"zh-TW":["二級市場"],"en":["a market where previously issued securities are bought and sold"]}', NULL, 'trade on the secondary market / secondary market price / secondary market liquidity', '[{"en":"Investors can sell their shares on the secondary market.","zh-TW":"投資者可以在二級市場出售股票。"},{"en":"The secondary market provides liquidity for early investors.","zh-TW":"二級市場為早期投資者提供流動性。"}]', '{"antonym":"primary market"}', NULL, 5, 5867, NULL),
(5868, 'secondary offering', '/ˈsekəndəri ˈɒfərɪŋ/', 'noun', '{"zh-TW":["二次發行；增發"],"en":["the sale of additional shares by a listed company after its IPO"]}', NULL, 'complete a secondary offering / secondary offering proceeds', '[{"en":"The company raised 200 million through a secondary offering.","zh-TW":"公司通過二次發行籌集了2億元。"},{"en":"The secondary offering diluted existing shareholders by 5%.","zh-TW":"二次發行使現有股東的股份稀釋了5%。"}]', NULL, NULL, 5, 5868, NULL),
(5869, 'secondment', '/ˈsekəndmənt/', 'noun', '{"zh-TW":["借調；臨時派遣"],"en":["the temporary transfer of an employee to another role or organization"]}', NULL, 'secondment opportunity / on secondment / secondment agreement', '[{"en":"She went on a six-month secondment to the Singapore office.","zh-TW":"她被借調到新加坡辦公室工作六個月。"},{"en":"A secondment can broaden an employee''s skills and network.","zh-TW":"借調可以拓寬員工的技能和人際網絡。"}]', '{"verb":"second"}', NULL, 4, 5869, NULL),
(5870, 'secret', '/ˈsiːkrɪt/', 'noun', '{"zh-TW":["秘密"],"en":["something kept hidden"]}', NULL, 'trade secret / keep a secret', '[{"en":"That recipe is a trade secret.","zh-TW":"那個配方是商業機密。"},{"en":"The key to success is no secret.","zh-TW":"成功的關鍵不是秘密。"}]', '{"noun":"secret","adjective":"secret","noun2":"secrecy","adverb":"secretly"}', NULL, 2, 5870, NULL),
(5871, 'section', 'ˈsɛkʃən', 'noun', '{"zh-TW":["部分；章節","科室"],"en":["a distinct part of something","a department or subdivision"]}', NULL, 'first section/cross-section', '[{"en":"Please read the first section carefully.","zh-TW":"請仔細閱讀第一部分。"}]', '{"verb":"section","adjective":"sectional","adverb":"sectionly"}', NULL, 3, 5871, NULL),
