(5873, 'secular', '/ˈsekjʊlər/', 'adjective', '{"zh-TW":["長期的；世俗的；非宗教的"],"en":["not connected with religious or spiritual matters; occurring over an extended period"]}', NULL, 'secular trend / secular stagnation / secular decline', '[{"en":"The secular decline in interest rates has compressed returns for fixed income investors.","zh-TW":"利率的長期下降壓縮了固定收益投資者的回報。"},{"en":"Secular stagnation describes a prolonged period of slow economic growth.","zh-TW":"長期停滯描述了一段持續緩慢的經濟增長時期。"}]', '{"adverb":"secularly","noun":"secularism"}', NULL, 3, 5873, NULL),
(5874, 'secularism', '/ˈsekjʊlərɪzəm/', 'noun', '{"zh-TW":["世俗主義；政教分離"],"en":["the principle of separation between religion and state or public life"]}', NULL, 'promote secularism / political secularism / secularism in education', '[{"en":"Secularism protects freedom of religion by keeping the state neutral.","zh-TW":"世俗主義通過保持國家中立來保護宗教自由。"},{"en":"The debate over secularism in public schools remains highly contested.","zh-TW":"關於公立學校世俗主義的辯論仍然極具爭議性。"}]', '{"adjective":"secular","adverb":"secularly"}', NULL, 4, 5874, NULL),
(5875, 'secure', '/sɪˈkjʊr/', 'adjective, verb', '{"zh-TW":["安全的；穩固的","獲得；確保"],"en":["safe from threat","to obtain or achieve"]}', NULL, 'secure a deal / secure environment / job security', '[{"en":"We secured a major contract with the client.","zh-TW":"我們與客戶簽下了一份大合約。"},{"en":"The building has a secure entrance.","zh-TW":"這棟建築有一個安全的入口。"}]', '{"noun":"security","verb":"secure","adjective":"secure, insecure","adverb":"securely"}', NULL, 2, 5875, 213),
(5876, 'secured creditor', '/sɪˈkjʊərd ˈkredɪtər/', 'noun', '{"zh-TW":["有擔保債權人"],"en":["a lender who holds collateral against a debt obligation"]}', NULL, 'rights of secured creditors / secured creditor priority', '[{"en":"Secured creditors have priority over unsecured creditors in insolvency.","zh-TW":"有擔保債權人在破產時優先於無擔保債權人。"},{"en":"The bank acted as a secured creditor with a charge over company assets.","zh-TW":"銀行作為有擔保債權人，對公司資產持有抵押權。"}]', '{"opposite":"unsecured creditor"}', NULL, 5, 5876, NULL),
(5877, 'secured debt', '/sɪˈkjʊərd det/', 'noun', '{"zh-TW":["有擔保債務"],"en":["debt backed by collateral that the lender can claim if the borrower defaults"]}', NULL, 'carry secured debt / secured debt obligation', '[{"en":"Secured debt is less risky for lenders because it is backed by assets.","zh-TW":"有擔保債務對貸款方風險較低，因為有資產擔保。"},{"en":"Secured debt holders have priority over unsecured creditors in bankruptcy.","zh-TW":"在破產時，有擔保債務持有人優先於無擔保債權人。"}]', '{"opposite":"unsecured debt"}', NULL, 4, 5877, NULL),
(5878, 'secured loan', '/sɪˈkjʊərd loʊn/', 'noun', '{"zh-TW":["有擔保貸款"],"en":["a loan backed by collateral that the lender can claim if repayment fails"]}', NULL, 'apply for a secured loan / secured loan interest rate', '[{"en":"The company obtained a secured loan using its property as collateral.","zh-TW":"公司以其物業作抵押獲得了有擔保貸款。"},{"en":"Secured loans typically offer lower interest rates than unsecured ones.","zh-TW":"有擔保貸款通常比無擔保貸款提供更低的利率。"}]', '{"opposite":"unsecured loan"}', NULL, 4, 5878, NULL),
(5879, 'securities', '/sɪˈkjʊərɪtiz/', 'noun', '{"zh-TW":["證券"],"en":["tradeable financial instruments including stocks and bonds"]}', NULL, 'invest in securities / trade securities / issue securities', '[{"en":"The fund invests in a mix of equities and fixed income securities.","zh-TW":"基金投資於股票和固定收益證券的組合。"},{"en":"Securities must be registered before they can be sold to the public.","zh-TW":"證券在向公眾出售前必須進行登記。"}]', '{"singular":"security","adjective":"secured"}', NULL, 4, 5879, NULL),
(5880, 'securitization', '/sɪˌkjʊərɪtɪˈzeɪʃən/', 'noun', '{"zh-TW":["資產證券化"],"en":["pooling financial assets and selling them as securities to investors"]}', NULL, 'mortgage securitization / asset securitization / securitization market', '[{"en":"Securitization allows banks to free up capital for new loans.","zh-TW":"資產證券化使銀行能夠釋放資本用於新貸款。"},{"en":"The securitization of subprime mortgages contributed to the financial crisis.","zh-TW":"次級抵押貸款的證券化加劇了金融危機。"}]', '{"verb":"securitize","adjective":"securitized"}', NULL, 5, 5880, NULL),
(5881, 'securitize', '/sɪˈkjʊərɪtaɪz/', 'verb', '{"zh-TW":["證券化"],"en":["to convert an asset or group of assets into a marketable security"]}', NULL, 'securitize loans / securitize mortgages / securitize receivables', '[{"en":"Banks securitize mortgage loans to free up capital for new lending.","zh-TW":"銀行將抵押貸款證券化以騰出資本用於新貸款。"},{"en":"The process of securitizing assets creates structured financial products.","zh-TW":"資產證券化過程創建了結構化金融產品。"}]', '{"noun":"securitization","adjective":"securitized"}', NULL, 4, 5881, NULL),
