(5891, 'segregation of duties', '/ˌseɡrɪˈɡeɪʃən əv ˈdjuːtɪz/', 'noun', '{"zh-TW":["職責分離"],"en":["the division of critical tasks among different people to prevent fraud"]}', NULL, 'implement segregation of duties / segregation of duties control', '[{"en":"Segregation of duties requires different people to authorize and process payments.","zh-TW":"職責分離要求不同的人授權和處理付款。"},{"en":"Lack of segregation of duties is a major internal control weakness.","zh-TW":"缺乏職責分離是主要的內部控制薄弱環節。"}]', NULL, NULL, 5, 5891, NULL),
