(5895, 'self-efficacy', '/''self ˌefɪkəsi/', 'noun', '{"zh-TW":["自我效能感"],"en":["one''s belief in their own ability to succeed at specific tasks or achieve certain goals"]}', NULL, 'build self-efficacy / high self-efficacy / self-efficacy theory', '[{"en":"Students with high self-efficacy are more likely to persist through academic challenges.","zh-TW":"具有高自我效能感的學生更可能在學業挑戰中堅持下去。"},{"en":"Building self-efficacy in employees through achievable goals improves overall motivation.","zh-TW":"通過可實現的目標在員工中建立自我效能感可以提升整體動力。"}]', '{"adjective":"efficacious","noun2":"efficacy"}', NULL, 5, 5895, NULL),
(5896, 'self-guided', '/''selfˌɡaɪdɪd/', 'adjective', '{"zh-TW":["自助的；自行導覽的"],"en":["relating to travel or a tour conducted without a professional guide"]}', NULL, 'self-guided tour / self-guided walk / self-guided itinerary', '[{"en":"The museum offers a self-guided audio tour using a smartphone app.","zh-TW":"博物館提供使用智慧手機應用程式的自助語音導覽。"},{"en":"She preferred a self-guided approach so she could explore at her own pace.","zh-TW":"她偏好自助方式，這樣她可以按自己的節奏探索。"}]', NULL, NULL, 4, 5896, NULL),
(5897, 'self-regulation', '/ˌself ˌreɡjʊˈleɪʃən/', 'noun', '{"zh-TW":["自律；自我調節"],"en":["the ability of a body to control its own behavior without external intervention"]}', NULL, 'industry self-regulation / self-regulation mechanism / rely on self-regulation', '[{"en":"Critics argue that industry self-regulation is insufficient to protect consumers.","zh-TW":"批評者認為，行業自律不足以保護消費者。"},{"en":"Financial market self-regulation failed to prevent the 2008 banking crisis.","zh-TW":"金融市場自律未能阻止二○○八年的銀行業危機。"}]', '{"verb":"self-regulate","adjective":"self-regulated"}', NULL, 5, 5897, NULL),
